css:
.d-wipe{position:relative;width:296px;max-width:100%;height:132px;overflow:hidden;border:1px solid var(--line);border-radius:10px;font-family:var(--sans);outline:none;cursor:pointer}
.d-wipe:focus-visible{outline:1px solid var(--ink);outline-offset:2px}
.d-wipe-a,.d-wipe-b{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:flex-end;gap:2px;padding:var(--sp-12)}
.d-wipe-a{background:var(--paper);color:var(--muted)}
.d-wipe-b{background:#2b4b8f;color:var(--paper);clip-path:polygon(0 0,0 0,0 100%,0 100%)}
.d-wipe-k{font-family:var(--mono);font-size:var(--fs-9);letter-spacing:.08em;opacity:.75}
.d-wipe-l{font-size:var(--fs-21);font-weight:600;letter-spacing:-.02em}
.d-wipe.is-on .d-wipe-b{animation:d-transition-wipe-diagonal-in 280ms cubic-bezier(.2,.75,.25,1) forwards}
.d-wipe.is-on .d-wipe-b .d-wipe-l{animation:d-transition-wipe-diagonal-text 280ms cubic-bezier(.2,.75,.25,1) forwards}
.d-wipe.is-out .d-wipe-b{animation:d-transition-wipe-diagonal-out 280ms cubic-bezier(.2,.75,.25,1) forwards}
@keyframes d-transition-wipe-diagonal-in{from{clip-path:polygon(0 0,0 0,0 100%,0 100%)}to{clip-path:polygon(0 0,128% 0,108% 100%,0 100%)}}
@keyframes d-transition-wipe-diagonal-out{from{clip-path:polygon(0 0,128% 0,108% 100%,0 100%)}to{clip-path:polygon(0 0,0 0,0 100%,0 100%)}}
@keyframes d-transition-wipe-diagonal-text{from{transform:translateX(-10px)}to{transform:translateX(0)}}

init:
root => {
  const box = root.querySelector('.d-wipe');
  if (!box || box.dataset.dwd) return;
  box.dataset.dwd = '1';
  const on = () => {
    clearTimeout(box._dwT);
    box.classList.remove('is-out');
    box.classList.add('is-on');
  };
  const off = () => {
    clearTimeout(box._dwT);
    box.classList.add('is-out');
    box._dwT = setTimeout(() => {
      box.classList.remove('is-on');
      box.classList.remove('is-out');
    }, 280);
  };
  box._dwT = setTimeout(on, 280);
  box.addEventListener('click', () => { if (box.classList.contains('is-on')) off(); else on(); });
  box.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      if (box.classList.contains('is-on')) off(); else on();
    }
  });
}
